import paths from '../data/brand-paths.json';

/*
 * Manufacturer marks from the open Simple Icons set (CC0 artwork; the marks themselves remain the
 * property of their owners and are shown only to identify the car). Generated by tools/brand-icons.mjs.
 * Makes without a mark fall back to their name set in type.
 */
const NS = 'http://www.w3.org/2000/svg';
const KEY = { 'Acura / Honda': 'Honda' };

/** SVG element for a make's logo, or null when the icon set has no mark for it. */
export function brandMark(make) {
  const d = paths[KEY[make] || make];
  if (!d) return null;
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('role', 'img');
  svg.setAttribute('aria-label', `${make} logo`);
  svg.setAttribute('class', 'mark');
  const path = document.createElementNS(NS, 'path');
  path.setAttribute('d', d);
  svg.appendChild(path);
  return svg;
}
